INSERT INTO `case_version` VALUES (1,88,1132,1,'0713d96fe0e47c9370f1e4a65d9c68e7fc664a45b27f84cb9241ee71577f9cfd','{\"rowNum\":4,\"caseCode\":\"IM-FUN-001\",\"title\":\"BMC/BIOS网卡资产识别\",\"category\":\"基础管理测试\",\"priority\":\"P0\",\"precondition\":\"1. GPU01已安装2张CX7网卡，Ubuntu正常运行。\\n2. BMC可访问，且允许在维护窗口进入BIOS查看PCIe设备。\",\"expected\":\"1. Ubuntu可识别2张CX7，PCI ID为15b3:1021。\\n2. BMC与BIOS均能识别对应网卡/PCIe设备，无遗漏。\\n3. 三方显示的设备数量、身份及槽位等可比字段一致；不支持展示的字段不得判为已验证。\",\"domainTag\":\"\",\"capability\":\"\",\"description\":\"\",\"safetyLevel\":\"\",\"categoryL2\":\"BMC/BIOS识别\",\"sourcePriority\":\"T0\",\"caseClass\":\"导入\",\"testCategory\":\"\",\"ed202Coverage\":\"GPU01，ens17np0，400G，172.30.1.1，mlx5_0\\nGPU01，ens24np0，400G，172.30.2.1，mlx5_1\",\"sourceSheet\":\"Import详细测试流程\",\"steps\":[\"在GPU01查询两张CX7的PCI设备身份。\",\"从BMC的PCIe资源中核对两张网卡与槽位17、24的对应关系。\",\"在BIOS独立设备枚举界面核对同两张网卡。\",\"保存三方记录；仅查看BIOS设置不能代替设备枚举。\"],\"sourceRow\":4}','import',1,'2026-11-10 20:53:36.396',17),(2,88,1133,1,'2241c1303d27723068c78897220727f74dedd411c35e5d62f6056d10f521f4de','{\"rowNum\":5,\"caseCode\":\"IM-FUN-002\",\"title\":\"BMC SMBus/I2C网卡识别\",\"category\":\"基础管理测试\",\"priority\":\"P0\",\"precondition\":\"1. GPU01已安装CX7，BMC（172.31.10.11）可登录。\\n2. BMC与CX7具备实际SMBus/I2C管理连接。\\n3. BMC提供相应的只读诊断或设备枚举接口。\",\"expected\":\"1. BMC能够在正确的SMBus/I2C通道发现目标CX7对应的设备地址，并取得有效的设备识别信息或经厂商定义的只读响应。\\n2. 枚举结果与目标网卡所在插槽/管理链路映射一致，无误识别。\\n3. 若硬件未连接该总线或BMC不提供识别能力，记录“不适用/环境受限”，不得凭Ubuntu PCIe识别判定通过。\",\"domainTag\":\"\",\"capability\":\"\",\"description\":\"\",\"safetyLevel\":\"\",\"categoryL2\":\"BMC/BIOS识别\",\"sourcePriority\":\"T0\",\"caseClass\":\"导入\",\"testCategory\":\"\",\"ed202Coverage\":\"GPU01，ens17np0，400G，172.30.1.1，mlx5_0\\nGPU01，ens24np0，400G，172.30.2.1，mlx5_1\",\"sourceSheet\":\"Import详细测试流程\",\"steps\":[\"服务器上电，BMC 启动完成后，通过 BMC Web 或 SSH 进入 BMC 命令行。\",\"执行 SMBus 设备扫描命令，扫描网卡对应 SMBus 通道的从设备地址。\",\"定位网卡对应的 I2C 从设备地址。\",\"读取对应地址寄存器，验证厂商标识、产品标识、MAC 地址等基础硬件信息。\"],\"sourceRow\":5}','import',1,'2026-11-10 20:53:36.415',17),(3,88,1134,1,'71e3768fd9c0cce99b2a2e53928ca447172764508d858943211cb3e33fdaad46','{\"rowNum\":6,\"caseCode\":\"IM-FUN-003\",\"title\":\"BMC MCTP/SMBus端点识别\",\"category\":\"基础管理测试\",\"priority\":\"P2\",\"precondition\":\"1. GPU01已安装CX7，BMC（172.31.10.11）可登录。\\n2. CX7与BMC之间具备SMBus管理通路。\\n3. BMC固件支持MCTP over SMBus端点查询。\",\"expected\":\"1. BMC可通过MCTP over SMBus发现目标CX7端点，取得有效EID及可识别的管理响应。\\n2. 端点所属SMBus管理通道与实际CX7插槽映射一致。\\n3. 若未配置相应硬件通路或固件不支持，记录“不适用/环境受限”，不得仅凭PCIe枚举判定通过。\",\"domainTag\":\"\",\"capability\":\"\",\"description\":\"\",\"safetyLevel\":\"\",\"categoryL2\":\"BMC/BIOS识别\",\"sourcePriority\":\"T2\",\"caseClass\":\"导入\",\"testCategory\":\"\",\"ed202Coverage\":\"GPU01，ens17np0，400G，172.30.1.1，mlx5_0\\nGPU01，ens24np0，400G，172.30.2.1，mlx5_1\",\"sourceSheet\":\"Import详细测试流程\",\"steps\":[\"服务器上电，BMC 正常运行，确认网卡 SMBus 链路与 BMC 连通。\",\"进入 BMC 管理界面「MCTP 配置」或 BMC Shell 执行 MCTP 总线枚举命令。\",\"扫描 SMBus 通道的 MCTP 端点，查看网卡对应的端点 ID、设备类型。\",\"进入端点详情页，读取 FRU 部件号 / 序列号、固件版本、温度传感器、端口链路状态等管理数据。\"],\"sourceRow\":6}','import',1,'2026-11-10 20:53:36.426',17),(4,88,1135,1,'048e6070fdd86d2b3c69760f64f24cc4be3218b6f89fe3274a302e3f3d095792','{\"rowNum\":7,\"caseCode\":\"IM-FUN-004\",\"title\":\"BMC MCTP/PCIe端点识别\",\"category\":\"基础管理测试\",\"priority\":\"P1\",\"precondition\":\"1. GPU01已安装CX7，BMC（172.31.10.11）可登录。\\n2. BMC平台与CX7支持通过PCIe VDM传输MCTP消息。\\n3. BMC具备MCTP端点发现及查询能力。\",\"expected\":\"1. 能在PCIe VDM传输上发现CX7的MCTP端点，获得有效EID及管理响应。\\n2. 端点与实际CX7 PCIe设备/插槽对应正确。\\n3. 若平台不具备该MCTP传输路径，记录“不适用/环境受限”；普通PCIe枚举不作为通过证据。\",\"domainTag\":\"\",\"capability\":\"\",\"description\":\"\",\"safetyLevel\":\"\",\"categoryL2\":\"BMC/BIOS识别\",\"sourcePriority\":\"T1\",\"caseClass\":\"导入\",\"testCategory\":\"\",\"ed202Coverage\":\"GPU01，ens17np0，400G，172.30.1.1，mlx5_0\\nGPU01，ens24np0，400G，172.30.2.1，mlx5_1\",\"sourceSheet\":\"Import详细测试流程\",\"steps\":[\"服务器开机完成 PCIe 链路训练，BMC 开启 PCIe MCTP 支持。\",\"进入 BMC「PCIe MCTP 配置」界面或执行对应 CLI 枚举命令。\",\"扫描对应 PCIe 插槽 / 总线的 MCTP VDM 端点，匹配对应网卡设备。\",\"读取端点管理信息：PCIe 链路速率 / 宽度、端口数量、支持速率、功能启用状态。\"],\"sourceRow\":7}','import',1,'2026-11-10 20:53:36.433',17),(5,88,1136,1,'96609be39f85dece80b7be24b703daa59c19c46a24ccd82b4ce1b2d40609f580','{\"rowNum\":8,\"caseCode\":\"IM-FUN-005\",\"title\":\"BMC NC-SI边带端口识别\",\"category\":\"基础管理测试\",\"priority\":\"P2\",\"precondition\":\"1. GPU01已安装CX7，BMC（172.31.10.11）可登录。\\n2. 服务器具备连接BMC与CX7的NC-SI边带通路。\\n3. BMC可提供NC-SI通道状态或诊断信息。\",\"expected\":\"1. BMC能够识别与CX7对应的NC-SI Package/Channel，并取得有效通道信息或协议响应。\\n2. 通道与目标网卡/物理端口映射一致，无误识别。\\n3. 如设备无NC-SI物理通路或BMC不支持，记录“不适用/环境受限”，不能用BMC管理网络可登录代替验证。\",\"domainTag\":\"\",\"capability\":\"\",\"description\":\"\",\"safetyLevel\":\"\",\"categoryL2\":\"BMC/BIOS识别\",\"sourcePriority\":\"T2\",\"caseClass\":\"导入\",\"testCategory\":\"\",\"ed202Coverage\":\"GPU01，ens17np0，400G，172.30.1.1，mlx5_0\\nGPU01，ens24np0，400G，172.30.2.1，mlx5_1\",\"sourceSheet\":\"Import详细测试流程\",\"steps\":[\"确认网卡 NCSI 物理引脚与 BMC 边带链路连通，BMC 开启 NCSI 协议支持。\",\"进入 BMC 网络配置界面，导航至 NCSI 设置页面。\",\"查看 NCSI 设备列表，确认网卡对应端口号、PHY 地址、链路能力。\",\"选择该端口作为 BMC 共享网口，配置 IP 参数后验证远程网络连通性。\"],\"sourceRow\":8}','import',1,'2026-11-10 20:53:36.441',17),(6,88,1137,1,'0fa309de70dd7b33dc78d21a256f08abeba97f260509137864bfe4f965d5e973','{\"rowNum\":9,\"caseCode\":\"IM-FUN-006\",\"title\":\"BIOS PCIe设备枚举\",\"category\":\"基础管理测试\",\"priority\":\"P0\",\"precondition\":\"1. GPU01已安装CX7，具备BIOS/UEFI Setup访问权限。\\n2. 在维护窗口进行测试，记录目标网卡当前Option ROM设置，以便恢复。\",\"expected\":\"1. CPU0_PCIE4、CPU1_PCIE7均显示Linked as x16。\\n2. UEFI Shell枚举两张CX7，BDF为0000:45:00.0、0000:AC:00.0。\\n3. 两张网卡的PCI配置空间可读，VID/DID均为15B3:1021。\\n4. 两张CX7的BDF与BIOS插槽对应正确。\\n5. 未执行关闭Option ROM的对照，不据此判定关闭状态下的枚举能力。\",\"domainTag\":\"\",\"capability\":\"\",\"description\":\"\",\"safetyLevel\":\"\",\"categoryL2\":\"BMC/BIOS识别\",\"sourcePriority\":\"T0\",\"caseClass\":\"导入\",\"testCategory\":\"\",\"ed202Coverage\":\"GPU01，ens17np0，400G，172.30.1.1，mlx5_0\\nGPU01，ens24np0，400G，172.30.2.1，mlx5_1\",\"sourceSheet\":\"Import详细测试流程\",\"steps\":[\"进入GPU01 BIOS，查看CPU0_PCIE4与CPU1_PCIE7的链路状态。\",\"启动UEFI Shell，执行pci -b查找两张CX7。\",\"执行pci 45 00 00 -s 00读取第一张CX7配置空间。\",\"执行pci AC 00 00 -s 00读取第二张CX7配置空间。\",\"核对两张CX7的BDF、VID/DID及BIOS插槽映射。\"],\"sourceRow\":9}','import',1,'2026-11-10 20:53:36.447',17),(7,88,1138,1,'cb042e845c670fd1a49dc9a8a8f2fb8454cf96f9604c4a472e0e31e003d0b688','{\"rowNum\":10,\"caseCode\":\"IM-FUN-007\",\"title\":\"BIOS PCIe Option ROM识别\",\"category\":\"基础管理测试\",\"priority\":\"P2\",\"precondition\":\"1. GPU01的CX7具备可用的UEFI驱动或Option ROM组件。\\n2. BIOS支持加载相应组件。\\n3. 已安排维护窗口，具备BIOS修改权限并记录原配置。\",\"expected\":\"1. BIOS显示UEFI Only、Option ROM execution=Auto。\\n2. OEM NIC Oprom Ctrl中两张CX7均为Enabled。\\n3. UEFI识别两张网卡，MAC与实际设备一致。\\n4. 两张PCIe设备均绑定Mellanox ConnectX Driver。\\n5. 加载路径含Offset(0x29A38,0x755FF)，归属对应PCIe设备。\\n6. SNP/MNP/PXE/IPv4/IPv6协议句柄已创建，无加载错误。\",\"domainTag\":\"\",\"capability\":\"\",\"description\":\"\",\"safetyLevel\":\"\",\"categoryL2\":\"BMC/BIOS识别\",\"sourcePriority\":\"T2\",\"caseClass\":\"导入\",\"testCategory\":\"\",\"ed202Coverage\":\"GPU01，ens17np0，400G，172.30.1.1，mlx5_0\\nGPU01，ens24np0，400G，172.30.2.1，mlx5_1\",\"sourceSheet\":\"Import详细测试流程\",\"steps\":[\"在GPU01 BIOS的Advanced → CSM Configuration查看启动及ROM策略。\",\"在Advanced → OEM NIC Oprom Ctrl确认两张CX7为Enabled。\",\"进入UEFI Shell，执行devices -b定位两张网卡句柄。\",\"执行dh -d 256、dh -d 289核对PCIe设备驱动绑定。\",\"执行dh 2C3 -v、dh 2C6 -v检查驱动镜像加载路径。\",\"执行dh -d 2FF、dh -d 356核对网卡身份与MAC。\",\"核对SNP/MNP/PXE/IPv4/IPv6协议句柄并保留回显。\"],\"sourceRow\":10}','import',1,'2026-11-10 20:53:36.455',17),(8,88,1139,1,'6260bf421365b33ac73e08b07e0bd8a1376d7edeaa70eb565eb98086e1ad1cc0','{\"rowNum\":11,\"caseCode\":\"IM-FUN-008\",\"title\":\"BIOS SMBus/I2C设备枚举\",\"category\":\"基础管理测试\",\"priority\":\"P2\",\"precondition\":\"1. GPU01（NF5468M7）已安装CX7，可进入BIOS/UEFI Setup。\\n2. 主板与CX7之间存在SMBus/I2C管理通路。\\n3. BIOS具备相应的设备枚举或查看功能，并已安排维护窗口。\",\"expected\":\"1. BIOS可枚举与目标CX7对应的SMBus/I2C设备，设备地址及通道/插槽映射与硬件设计一致。\\n2. 若BIOS没有该接口或主板无相应连接，记录“不适用/环境受限”，不得用BMC或Ubuntu的PCIe枚举代替。\",\"domainTag\":\"\",\"capability\":\"\",\"description\":\"\",\"safetyLevel\":\"\",\"categoryL2\":\"BMC/BIOS识别\",\"sourcePriority\":\"T2\",\"caseClass\":\"导入\",\"testCategory\":\"\",\"ed202Coverage\":\"GPU01，ens17np0，400G，172.30.1.1，mlx5_0\\nGPU01，ens24np0，400G，172.30.2.1，mlx5_1\",\"sourceSheet\":\"Import详细测试流程\",\"steps\":[\"进入GPU01 BIOS，打开厂商提供的SMBus/I2C设备或管理总线信息界面。\",\"查看CX7对应的设备地址、总线/通道及插槽映射，记录实际显示结果。\"],\"sourceRow\":11}','import',1,'2026-11-10 20:53:36.464',17),(9,88,1140,1,'779a2048b302f710b29f0e2cd7aa56b51650f7310cb6472c2de8907bdd515b15','{\"rowNum\":12,\"caseCode\":\"IM-FUN-009\",\"title\":\"BIOS MCTP端点识别\",\"category\":\"基础管理测试\",\"priority\":\"P2\",\"precondition\":\"1. GPU01可进入BIOS/UEFI Setup，具备维护权限。\\n2. BIOS支持MCTP端点发现。\\n3. CX7具备BIOS支持的MCTP管理传输路径。\",\"expected\":\"1. BIOS能发现目标CX7的MCTP端点，返回有效EID和管理响应，且设备/槽位映射正确。\\n2. BIOS不具备MCTP端点管理能力时记录“不适用/环境受限”；不能用BMC端点发现结果冒充BIOS验证。\",\"domainTag\":\"\",\"capability\":\"\",\"description\":\"\",\"safetyLevel\":\"\",\"categoryL2\":\"BMC/BIOS识别\",\"sourcePriority\":\"T2\",\"caseClass\":\"导入\",\"testCategory\":\"\",\"ed202Coverage\":\"GPU01，ens17np0，400G，172.30.1.1，mlx5_0\\nGPU01，ens24np0，400G，172.30.2.1，mlx5_1\",\"sourceSheet\":\"Import详细测试流程\",\"steps\":[\"在GPU01 BIOS的厂商管理/设备信息界面查看MCTP端点列表。\",\"查询目标CX7对应端点的EID、传输通道和有效管理响应，核对PCIe设备或槽位映射。\"],\"sourceRow\":12}','import',1,'2026-11-10 20:53:36.469',17),(10,88,1141,1,'8dedfdab48b35c1ba9f414784095ff644f13048209d2f5d1fed0e8104ce3c65f','{\"rowNum\":13,\"caseCode\":\"IM-FUN-010\",\"title\":\"BIOS NC-SI端口配置识别\",\"category\":\"基础管理测试\",\"priority\":\"P2\",\"precondition\":\"1. GPU01可进入BIOS/UEFI Setup。\\n2. 主板与CX7之间存在NC-SI边带连接。\\n3. BIOS支持读取NC-SI通道及端口配置。\",\"expected\":\"1. BIOS可识别目标CX7对应NC-SI通道及配置，Package/Channel或端口映射与硬件一致。\\n2. 若主板未连接NC-SI或BIOS无相关界面，记录“不适用/环境受限”；不能仅以BMC可登录判定通过。\",\"domainTag\":\"\",\"capability\":\"\",\"description\":\"\",\"safetyLevel\":\"\",\"categoryL2\":\"BMC/BIOS识别\",\"sourcePriority\":\"T2\",\"caseClass\":\"导入\",\"testCategory\":\"\",\"ed202Coverage\":\"GPU01，ens17np0，400G，172.30.1.1，mlx5_0\\nGPU01，ens24np0，400G，172.30.2.1，mlx5_1\",\"sourceSheet\":\"Import详细测试流程\",\"steps\":[\"进入GPU0