  `batch_id` bigint NOT NULL COMMENT '逻辑引用 import_batch.id',
  `row_no` int NOT NULL COMMENT '批内行序号（1-based，稳定）',
  `case_code` varchar(128) DEFAULT NULL,
  `action` varchar(16) NOT NULL COMMENT 'NEW / UPDATE / UNCHANGED / DEPRECATE',
  `message` varchar(512) DEFAULT NULL,
  `payload_json` mediumtext COMMENT '原始行快照，提交时据此落库',
  `case_id` bigint DEFAULT NULL COMMENT '提交后指向 test_case.id',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_import_item` (`batch_id`,`row_no`),
  KEY `idx_import_item_batch` (`batch_id`,`action`)
) ENGINE=InnoDB AUTO_INCREMENT=2191 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='导入批次逐行明细（v4.6.0）';
/*!40101 SET character_set_client = @saved_cs_client */;

